    for (rs, re) in row_intervals:
        for (cs, ce) in col_intervals:
            region = []
            for r in range(rs, re + 1):
                for c in range(cs, ce + 1):
                    region.append(grid[r][c])

            if not region:
                continue

            counts = Counter(region)
            max_count = max(counts.values())
            background = max(counts, key=counts.get)
            region_size = len(region)
            noise_count = region_size - max_count

            # FLIP to noise only if density > 33.3% (noise_count > region_size / 3)
            if noise_count > region_size / 3:
                noise_color = min(counts, key=counts.get)
                for r in range(rs, re + 1):
                    for c in range(cs, ce + 1):
                        output[r][c] = noise_color
            else:
                # Clean to background (keep majority)
                for r in range(rs, re + 1):
                    for c in range(cs, ce + 1):
                        output[r][c] = background

    return output
